import 'package:cephalopod/features/game/presentation/models/die_ui.dart';
import 'package:cephalopod/features/game/presentation/models/square_mark.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'square_ui.freezed.dart';

/// One square of the board: where it is, counting [row] and [col] from 0 at
/// the top left, the [die] on it, if any, and how it stands out ([mark]).
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
abstract class SquareUi with _$SquareUi {
  const factory SquareUi({
    required int row,
    required int col,
    required DieUi? die,
    required SquareMark mark,
  }) = _SquareUi;
}
